mapper.update:
UPDATE challenge_user
SET is_refunded   = TRUE,
    refund_amount = #{refundAmount},
    completed_at  = NOW()
WHERE challenge_id = #{challengeId}
  AND user_id      = #{userId}

UPDATE challenge
SET challenge_status = 'ENDED'
WHERE challenge_id = #{challengeId}

UPDATE challenge_finance
SET success_headcount = success_headcount + 1,
    total_refund      = total_refund + #{refundAmount}
WHERE challenge_id = #{challengeId}

UPDATE challenge_finance cf
SET cf.success_headcount = (
        SELECT COUNT(*) FROM challenge_user cu
        WHERE cu.challenge_id = #{challengeId} AND cu.is_refunded = TRUE
    ),
    cf.total_refund = (
        SELECT COALESCE(SUM(cu.refund_amount), 0) FROM challenge_user cu
        WHERE cu.challenge_id = #{challengeId} AND cu.is_refunded = TRUE
    )
WHERE cf.challenge_id = #{challengeId}
